MODULE DIST_SPEC_ARGS_INFO_MOD

USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT

IMPLICIT NONE

PRIVATE
PUBLIC :: ARGS_INFO

! Shapes of the array arguments to DIST_SPEC
TYPE, BIND(C) :: ARGS_INFO
  INTEGER(KIND=C_INT) :: IPSPECG_SHAPE(2)
  INTEGER(KIND=C_INT) :: IKFROM_SHAPE(1)
  INTEGER(KIND=C_INT) :: IKVSET_SHAPE(1)
  INTEGER(KIND=C_INT) :: IPSPEC_SHAPE(2)
  INTEGER(KIND=C_INT) :: IKSORT_SHAPE(1)
END TYPE ARGS_INFO

END MODULE DIST_SPEC_ARGS_INFO_MOD

SUBROUTINE DIST_SPEC(PSPECG, KFDISTG, KFROM, KVSET, KRESOL, PSPEC, LDIM1_IS_FLD, KSMAX, KSORT)

USE PARKIND1,                    ONLY: JPRB, JPIM
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_BOOL, C_PTR, C_LOC, C_NULL_PTR
USE DIST_SPEC_ARGS_INFO_MOD,     ONLY: ARGS_INFO

IMPLICIT NONE

INTERFACE
SUBROUTINE DIST_SPEC_CPP_BINDING_SP(ARGS, KDIM1_IS_FLD, KFDISTG, KRESOL, KSMAX, PSPECG, KFROM, &
  &                                 KVSET, PSPEC, KSORT) BIND(C, NAME="dist_spec_sp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_FLOAT, C_INT, C_PTR
  USE DIST_SPEC_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KDIM1_IS_FLD
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KFDISTG
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KSMAX
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(IN)  :: PSPECG(*)
  INTEGER(KIND=C_INT),           INTENT(IN)  :: KFROM(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSET(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT) :: PSPEC(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KSORT(*)
END SUBROUTINE DIST_SPEC_CPP_BINDING_SP
SUBROUTINE DIST_SPEC_CPP_BINDING_DP(ARGS, KDIM1_IS_FLD, KFDISTG, KRESOL, KSMAX, PSPECG, KFROM, &
  &                                 KVSET, PSPEC, KSORT) BIND(C, NAME="dist_spec_dp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_DOUBLE, C_INT, C_PTR
  USE DIST_SPEC_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KDIM1_IS_FLD
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KFDISTG
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KSMAX
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(IN)  :: PSPECG(*)
  INTEGER(KIND=C_INT),           INTENT(IN)  :: KFROM(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSET(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT) :: PSPEC(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KSORT(*)
END SUBROUTINE DIST_SPEC_CPP_BINDING_DP
END INTERFACE

REAL(KIND=JPRB),    OPTIONAL, INTENT(IN)  :: PSPECG(:,:)
INTEGER(KIND=JPIM),           INTENT(IN)  :: KFDISTG
INTEGER(KIND=JPIM),           INTENT(IN)  :: KFROM(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KVSET(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KRESOL
REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT) :: PSPEC(:,:)
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDIM1_IS_FLD
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KSMAX
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KSORT(:)

TYPE(ARGS_INFO) :: ARGS

TYPE(C_PTR) :: KDIM1_IS_FLD_PTR, KRESOL_PTR, KSMAX_PTR
LOGICAL(KIND=C_BOOL), TARGET :: LDIM1_FLD
INTEGER(KIND=C_INT),  TARGET :: IRESOL, ISMAX

IF (PRESENT(PSPECG)) THEN
  ARGS%IPSPECG_SHAPE = SHAPE(PSPECG, KIND=C_INT)
ELSE
  ARGS%IPSPECG_SHAPE = 0_C_INT
ENDIF
ARGS%IKFROM_SHAPE = SHAPE(KFROM, KIND=C_INT)
IF (PRESENT(KVSET)) THEN
  ARGS%IKVSET_SHAPE = SHAPE(KVSET, KIND=C_INT)
ELSE
  ARGS%IKVSET_SHAPE = 0_C_INT
ENDIF
IF (PRESENT(PSPEC)) THEN
  ARGS%IPSPEC_SHAPE = SHAPE(PSPEC, KIND=C_INT)
ELSE
  ARGS%IPSPEC_SHAPE = 0_C_INT
ENDIF
IF (PRESENT(KSORT)) THEN
  ARGS%IKSORT_SHAPE = SHAPE(KSORT, KIND=C_INT)
ELSE
  ARGS%IKSORT_SHAPE = 0_C_INT
ENDIF

IF (PRESENT(LDIM1_IS_FLD)) THEN
  LDIM1_FLD = LDIM1_IS_FLD
  KDIM1_IS_FLD_PTR = C_LOC(LDIM1_FLD)
ELSE
  KDIM1_IS_FLD_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KRESOL)) THEN
  IRESOL = KRESOL
  KRESOL_PTR = C_LOC(IRESOL)
ELSE
  KRESOL_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KSMAX)) THEN
  ISMAX = KSMAX
  KSMAX_PTR = C_LOC(ISMAX)
ELSE
  KSMAX_PTR = C_NULL_PTR
ENDIF

#ifdef TRANS_SINGLE
CALL DIST_SPEC_CPP_BINDING_SP(ARGS, KDIM1_IS_FLD_PTR, KFDISTG, KRESOL_PTR, KSMAX_PTR, &
  &                           PSPECG=PSPECG, KFROM=KFROM, KVSET=KVSET, PSPEC=PSPEC, KSORT=KSORT)
#else
CALL DIST_SPEC_CPP_BINDING_DP(ARGS, KDIM1_IS_FLD_PTR, KFDISTG, KRESOL_PTR, KSMAX_PTR, &
  &                           PSPECG=PSPECG, KFROM=KFROM, KVSET=KVSET, PSPEC=PSPEC, KSORT=KSORT)
#endif

END SUBROUTINE DIST_SPEC
